 if(in_array($tab,['count','manual'],true)&&can_action('upload_inventory_count')){$parent=(int)($_GET['supersedes']??0);$prev=$parent?count_batch($parent):null;$meta=$prev?final_count_meta($prev):[];echo '<div class="card"><h3>Create '.($tab==='manual'?'Manual':'Upload').' Final-Count Attempt</h3><p>No mandatory recount. One final count per attempt; evidence cannot be overwritten. Correct mistakes by closing this attempt and starting a linked attempt.</p>';final_count_form('final_create');echo '<input type="hidden" name="entry_method" value="'.($tab==='manual'?'Manual':'Upload').'"><input type="hidden" name="supersedes" value="'.$parent.'">';if($prev)echo '<div class="alert info">Linked replacement for '.e($prev['batch_ref']).'. The original record and evidence will remain in history.</div>';echo '<div class="row"><label>Inventory Count Date<input type="date" name="count_date" max="'.date('Y-m-d').'" value="'.e($prev['count_date']??date('Y-m-d')).'" required></label><label>Count Scope<select name="count_scope"><option value="Sellable" '.(($meta['count_scope']??'Sellable')==='Sellable'?'selected':'').'>Sellable Only</option><option value="All Conditions" '.(($meta['count_scope']??'')==='All Conditions'?'selected':'').'>All Stock Conditions</option></select></label></div><p class="muted small">Past dates use that date’s end-of-day balance. Today captures the current cutoff. Linked corrected attempts retain the original cutoff when the count date is unchanged. Upload and posting dates are recorded separately. A closed period must be reopened by an authorized Admin.</p>';
 if($tab==='manual')echo '<div data-manual-products><div data-product-lines><div class="card stack" data-product-line><label>Product / Master SKU</label>'.picker('products[0][product_id]','Search product or SKU...',true,'',false).'<button type="button" class="btn ghost sm" data-remove-line>Remove Item</button></div></div><button type="button" class="btn ghost" data-add-product>+ Add Item Line</button></div>';
 else{echo '<label>Product / SKU / Brand Search<input name="q" placeholder="All matching active products"></label><label>Brand<select name="brand"><option value="">All Brands</option>';foreach(inventory_brand_options() as $v)echo '<option>'.e($v).'</option>';echo '</select></label>';}
 echo '<label class="ack"><input type="checkbox" name="cutoff_ack" value="1" required> The final counts represent the selected cutoff. Movements during counting were paused or reconciled; a multi-day count is not simply relabelled as the first day.</label><button class="btn primary">Create Final-Count Attempt</button></form></div>';}
 $where=$tab==='history'?"status IN ('Applied','Cancelled','Reversed')":($tab==='review'?"status IN ('Validated','Submitted','Awaiting Approval','Error','Recount Required','Recounted','Pending Review')":"status NOT IN ('Applied','Cancelled','Reversed')");$search=trim($_GET['search']??'');$offset=max(0,(int)($_GET['offset']??0));$q=db()->prepare("SELECT * FROM inventory_count_batches WHERE ($where) AND (batch_ref LIKE ? OR created_name LIKE ?) ORDER BY id DESC LIMIT 51 OFFSET $offset");$q->execute(['%'.$search.'%','%'.$search.'%']);$listTotal=rs8_list_total("SELECT COUNT(*) FROM inventory_count_batches WHERE ($where) AND (batch_ref LIKE ? OR created_name LIKE ?)",['%'.$search.'%','%'.$search.'%']);$batches=$q->fetchAll();echo '<div class="card"><form method="get" class="inline-form"><input type="hidden" name="page" value="inventory_count"><input type="hidden" name="tab" value="'.e($tab).'"><input name="search" value="'.e($search).'" placeholder="Reference / Created by"><button class="btn secondary">Search</button></form><div class="table-wrap"><table class="table"><tr><th>Reference</th><th>Count Cutoff</th><th>Status</th><th>Preparer</th><th>Reviewer</th><th>Approver</th><th></th></tr>';foreach(array_slice($batches,0,50) as $r)echo '<tr><td>'.e($r['batch_ref']).'</td><td>'.e($r['cutoff_at']?:$r['count_date']).'</td><td>'.e($r['status']==='Exported'&&final_count_is($r)?'Awaiting Final Count':$r['status']).'</td><td>'.e($r['created_name']).'</td><td>'.e($r['reviewed_name']?:'—').'</td><td>'.e($r['approved_name']?:'—').'</td><td><a class="btn ghost sm" href="?page=inventory_count&id='.$r['id'].'">View</a></td></tr>';echo '</table></div>';echo rs8_pagination($listTotal,$offset,50,array_replace($_GET,['page'=>'inventory_count','tab'=>$tab,'search'=>$search]));echo '</div>';return;
}
try{$b=count_batch($id);$meta=final_count_meta($b);$scope=$meta['count_scope'];$lines=count_lines($id);$closed=in_array($b['status'],['Applied','Cancelled','Reversed'],true);$owner=can_action('upload_inventory_count')&&(current_user()['role']==='Admin'||(int)$b['created_by']===current_user()['id']);$errors=json_decode($b['error_json']??'[]',true)?:[];
 echo '<div class="card"><h3>'.e($b['batch_ref']).' · Record #'.$id.'</h3><p><b>Status:</b> '.e($b['status']==='Exported'?'Awaiting Final Count':$b['status']).' · <b>Scope:</b> '.e($scope).'<br><b>Count Cutoff:</b> '.e($b['cutoff_at']).'<br><b>Created / Upload Attempt Started:</b> '.e($b['created_at']).'<br><b>Submitted:</b> '.e($meta['submitted_at']??'Not submitted').'<br><b>Posted:</b> '.e($b['applied_at']??'Not posted').'</p><p>Preparer: '.e($b['created_name']).' · Reviewer: '.e($b['reviewed_name']?:'Pending').' · Approver: '.e($b['approved_name']?:'Pending').'</p><div class="modal-actions"><a class="btn ghost" href="?page=inventory_count">All Attempts</a><a class="btn ghost" href="inventory_count.php?id='.$id.'&results=1">Download Validation Excel</a><a class="btn ghost" target="_blank" rel="noopener" href="inventory_count.php?id='.$id.'&results=1&format=print">Print / PDF</a></div>';if(!empty($meta['supersedes']))echo '<p>Linked previous attempt: <a href="?page=inventory_count&id='.(int)$meta['supersedes'].'">#'.(int)$meta['supersedes'].'</a></p>';echo '</div>';
