 else{echo '<div class="card"><h3>Upload One Final Count</h3><p>System quantities are hidden from the count sheet. '.($scope==='Sellable'?'Only Master SKU and Counted Quantity are required.':'Enter all four condition counts for every counted item.').' Blank is not counted; 0 means counted zero.</p><div class="modal-actions"><a class="btn secondary" href="inventory_count.php?id='.$id.'&download=1">Download Blind Inventory Sheet</a><a class="btn ghost" target="_blank" rel="noopener" href="inventory_count.php?id='.$id.'&print=1">Print Blank Count Sheet</a></div>';final_count_form('final_upload',$id,true);echo '<input type="file" name="file" accept=".xlsx" required>';final_count_reason_fields();echo '<button class="btn primary">Upload &amp; Validate Final Count</button></form></div>';}}
 $plan=null;$planError='';if(in_array($b['status'],['Validated','Submitted','Awaiting Approval'],true))try{final_count_check($id);$plan=final_count_plan($id);$expected=$b['status']==='Validated'?($meta['validation_digest']??''):($b['status']==='Submitted'?($meta['submitted_digest']??''):$b['review_digest']);if(!hash_equals((string)$expected,$plan['digest']))$planError='Stock or allocation changed after validation/submission. Close this attempt and validate a linked replacement against the updated movements.';}catch(Throwable $ex){$planError=$ex->getMessage();}
 if($planError)echo '<div class="alert danger">'.e($planError).'</div>';
 if($b['status']!=='Exported'){echo '<div class="card table-wrap"><h3>Final Count Validation</h3><p>Variance = Final Count − System Quantity at the selected cutoff. Approval applies the variance while preserving later movements.</p><table class="table"><tr><th>Product / Master SKU</th><th>System Quantity at Cutoff</th><th>Final Count</th><th>Variance</th><th>Current Before Posting</th><th>Projected / Recorded After Posting</th></tr>';$plans=$plan?array_column($plan['lines'],null,'line_id'):[];foreach($lines as $l){if($l['actual_count']===null)continue;$snap=json_decode($l['snapshot_conditions'],true);$actual=json_decode($l['final_conditions'],true);$posting=$plans[$l['id']]??json_decode($l['posting_json']??'null',true);$sys=$scope==='Sellable'?$snap['good']:array_sum($snap);$count=$scope==='Sellable'?$actual['good']:array_sum($actual);$before=$posting?($scope==='Sellable'?$posting['snapshot']['good']:array_sum($posting['snapshot'])):null;$after=$posting?($scope==='Sellable'?$posting['recount']['good']:array_sum($posting['recount'])):null;echo '<tr><td>'.e($l['master_sku']).'<br>'.e($l['product_name']).($scope==='All Conditions'?'<div class="muted small">Sellable / Packaging / Damaged / Other<br>System: '.e(implode(' / ',array_values($snap))).'<br>Counted: '.e(implode(' / ',array_values($actual))).'</div>':'').'</td><td>'.$sys.'</td><td>'.$count.'</td><td>'.($count-$sys).'</td><td>'.($before??'—').'</td><td>'.($after??'—').'</td></tr>';}echo '</table><p>Reason: '.e($b['reason']).'<br>Supporting Reference: '.e($b['support_reference']).'</p></div>';}
 if($plan&&(!$planError)&&$b['status']==='Validated'&&$owner){echo '<div class="card">';final_count_form('final_submit',$id);echo '<input type="hidden" name="revision" value="'.$b['revision'].'"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I validated the final counts, scope and cutoff. Counting-period movements were accounted for. Submit and lock this record for review.</label><button class="btn primary">Submit Validated Final Count</button></form></div>';}
 if($plan&&(!$planError)&&$b['status']==='Submitted'&&can_action('upload_inventory_count')){echo '<div class="card">';final_count_form('final_review',$id);echo '<input type="hidden" name="revision" value="'.$b['revision'].'"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed the locked final count, discrepancy, cutoff and supporting reference.</label><button class="btn primary">Complete Review &amp; Request Approval</button></form></div>';}
 if($plan&&(!$planError)&&$b['status']==='Awaiting Approval'&&current_user()['role']==='Admin'&&(int)$b['reviewed_by']!==current_user()['id']){echo '<div class="card">';final_count_form('final_post',$id);echo '<input type="hidden" name="digest" value="'.e($plan['digest']).'"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I approve the final count variance and resulting platform allocation.</label><button class="btn primary">Approve &amp; Post Adjustment</button></form></div>';}
 elseif($b['status']==='Awaiting Approval')echo '<div class="alert warn">Awaiting approval from a different Admin. Quantities remain locked; no stock adjustment has posted.</div>';
 if($plan||in_array($b['status'],['Applied','Reversed'],true)){$alloc=$plan?$plan['lines']:array_filter(array_map(fn($l)=>json_decode($l['posting_json']??'null',true),$lines));echo '<div class="card table-wrap"><h3>Final Platform Allocation</h3><p>20 / 40 / 40 applies to projected sellable stock after the adjustment. Update actual marketplaces manually after approval.</p><table class="table"><tr><th>Product</th><th>Lazada</th><th>Shopee</th><th>TikTok</th></tr>';foreach($alloc as $l)echo '<tr><td>'.e($l['product']).'</td><td>'.$l['final_platforms']['Lazada'].'</td><td>'.$l['final_platforms']['Shopee'].'</td><td>'.$l['final_platforms']['TikTok'].'</td></tr>';echo '</table></div>';}
 if(!$closed&&can_action('upload_inventory_count')&&($owner||in_array($b['status'],['Submitted','Awaiting Approval'],true))){echo '<div class="card"><h3>'.(in_array($b['status'],['Submitted','Awaiting Approval'],true)?'Return for Correction':'Back / Cancel Validation').'</h3><p>Close this attempt with a reason. A corrected file or entry belongs to a new linked attempt; the original evidence remains unchanged.</p>';final_count_form(in_array($b['status'],['Submitted','Awaiting Approval'],true)?'final_return':'final_cancel',$id);echo '<label>Required Reason<input name="reason" minlength="3" required></label><button class="btn ghost">Close Attempt — No Stock Adjustment</button></form></div>';}
 if(in_array($b['status'],['Cancelled','Reversed'],true)&&$owner)echo '<div class="card"><a class="btn primary" href="?page=inventory_count&tab='.e(($meta['entry_method']??'')==='Manual'?'manual':'count').'&supersedes='.$id.'">Create Linked Corrected Attempt</a></div>';
 if($b['status']==='Applied'&&can_action('reversal_request')){echo '<div class="card"><h3>Correct a Posted Mistake</h3><form method="post" action="actions.php" class="stack"><input type="hidden" name="action" value="reversal_request"><input type="hidden" name="return" value="corrections"><input type="hidden" name="source_type" value="Inventory Count"><input type="hidden" name="source_id" value="'.$id.'"><label>Correction Reason<input name="reason" minlength="3" required></label><button class="btn secondary">Request Linked Reversal</button></form></div>';}
 echo '<div class="card table-wrap"><h3>Permanent Attempt &amp; Approval History</h3><table class="table"><tr><th>Recorded At</th><th>Event</th><th>User</th><th>Details</th></tr>';$q=db()->prepare('SELECT v.*,u.name FROM count_review_events v LEFT JOIN users u ON u.id=v.user_id WHERE batch_id=? ORDER BY v.id');$q->execute([$id]);foreach($q as $event){$details=json_decode($event['details_json'],true)?:[];$text=[];foreach($details as $k=>$v){if(in_array($k,['hash','digest'],true)||($k==='supersedes'&&!$v))continue;if($k==='rule'){$text[]='Rule Version: '.($v['version']??'Recorded');continue;}if($k==='errors'&&!$v){$text[]='Errors: None';continue;}$text[]=ucwords(str_replace('_',' ',$k)).': '.(is_array($v)?implode('; ',array_map(fn($x)=>is_scalar($x)?(string)$x:'Recorded detail',$v)):(is_bool($v)?($v?'Yes':'No'):(string)$v));}echo '<tr><td>'.e($event['created_at']).'</td><td>'.e($event['event_type']).'</td><td>'.e($event['name']).'</td><td>'.e(implode(' · ',$text)).'</td></tr>';}echo '</table><h3>Original Final Count Evidence</h3><table class="table"><tr><th>Uploaded / Validated At</th><th>File / Entry</th><th>Validation Result</th><th></th></tr>';$q=db()->prepare('SELECT * FROM count_upload_evidence WHERE batch_id=? ORDER BY id');$q->execute([$id]);foreach($q as $v)echo '<tr><td>'.e($v['created_at']).'</td><td>'.e($v['filename']).'</td><td>'.e(implode(' · ',json_decode($v['errors_json'],true)?:['Validated'])).'</td><td>'.($v['stored_path']?'<a href="inventory_count.php?id='.$id.'&evidence='.$v['id'].'">Download Original</a>':'Permanent manual validation record').'</td></tr>';echo '</table><h3>Physical Adjustment &amp; Redistribution</h3><table class="table"><tr><th>Movement Date</th><th>Movement</th><th>Product</th><th>Physical Change</th><th>Sellable Change</th><th>Recorded At</th></tr>';$q=db()->prepare('SELECT m.*,p.name FROM adjustment_movements m JOIN products p ON p.id=m.product_id WHERE batch_id=? ORDER BY m.id');$q->execute([$id]);foreach($q as $m)echo '<tr><td>'.e($m['txn_date']).'</td><td>'.e($m['movement_type']).'</td><td>'.e($m['name']).'</td><td>'.$m['physical_delta'].'</td><td>'.$m['sellable_delta'].'</td><td>'.e($m['created_at']).'</td></tr>';echo '</table></div>';
}catch(Throwable $ex){echo '<div class="alert danger">'.e(safe_error_message($ex)).'</div>';}
